HRESULT Common(IDirect3DDevice9* d){HRESULT result=S_OK;auto set=[&](HRESULT hr){if(FAILED(hr)&&SUCCEEDED(result))result=hr;};set(d->SetVertexShader(nullptr));set(d->SetFVF(D3DFVF_XYZRHW|D3DFVF_TEX1));const D3DRENDERSTATETYPE states[]={D3DRS_ZENABLE,D3DRS_ZWRITEENABLE,D3DRS_STENCILENABLE,D3DRS_ALPHABLENDENABLE,D3DRS_SEPARATEALPHABLENDENABLE,D3DRS_ALPHATESTENABLE,D3DRS_SCISSORTESTENABLE,D3DRS_SRGBWRITEENABLE,D3DRS_FOGENABLE,D3DRS_CLIPPLANEENABLE,D3DRS_MULTISAMPLEANTIALIAS};for(auto state:states)set(d->SetRenderState(state,0));set(d->SetRenderState(D3DRS_CULLMODE,D3DCULL_NONE));set(d->SetRenderState(D3DRS_FILLMODE,D3DFILL_SOLID));set(d->SetRenderState(D3DRS_COLORWRITEENABLE,15));for(unsigned i=0;i<3;++i){set(d->SetSamplerState(i,D3DSAMP_MINFILTER,D3DTEXF_POINT));set(d->SetSamplerState(i,D3DSAMP_MAGFILTER,D3DTEXF_POINT));set(d->SetSamplerState(i,D3DSAMP_MIPFILTER,D3DTEXF_NONE));set(d->SetSamplerState(i,D3DSAMP_ADDRESSU,D3DTADDRESS_CLAMP));set(d->SetSamplerState(i,D3DSAMP_ADDRESSV,D3DTADDRESS_CLAMP));set(d->SetSamplerState(i,D3DSAMP_SRGBTEXTURE,FALSE));}return result;}
